 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    anchors = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 5]
    if len(anchors) < 2:
        return g

    # The template 5 is the one embedded in a colored motif; the other 5
    # marks where to place a translated copy of that motif.
    def nearby_count(p):
        r, c = p
        return sum(1 for rr in range(max(0, r-2), min(h, r+3))
                   for cc in range(max(0, c-2), min(w, c+3))
                   if (rr, cc) != p and g[rr][cc] != 0)

    source = max(anchors, key=nearby_count)
    target = min((p for p in anchors if p != source), key=nearby_count)
    sr, sc = source
    tr, tc = target
    offsets = []
    for r in range(max(0, sr-2), min(h, sr+3)):
        for c in range(max(0, sc-2), min(w, sc+3)):
            if (r, c) != source and g[r][c] != 0:
                offsets.append((r-sr, c-sc, g[r][c]))
    g[tr][tc] = 0
    for dr, dc, color in offsets:
        rr, cc = tr+dr, tc+dc
        if 0 <= rr < h and 0 <= cc < w:
            g[rr][cc] = color
    return g
